import * as G from './engine.js';
import * as L from './lab.js';
import * as B from './balance.js';

const app=document.querySelector('#lab-app');
const toastNode=document.querySelector('#lab-toast');
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const KIT_NAMES={bulwark:'Bulwark',caster:'Caster',duelist:'Duelist',breaker:'Breaker'};
const KIT_ACTIONS={bulwark:'Rod + shield · Arc Bolt / Wardcast',caster:'Rod + focus · Arc Bolt',duelist:'Blade + charm · Driving Strike',breaker:'Sword + shield · Driving Strike / Guardstrike'};
let setup={scenarioId:L.LAB_SCENARIOS[0]?.id||'',kit:'',seed:'1'};
let session=null,ratings={satisfaction:'',clarity:'',repetition:''},compareAll=false,delayTimer,toastTimer,attemptLock=false;

function toast(message){toastNode.textContent=message;toastNode.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toastNode.classList.remove('show'),2600);}
function actionButton(action,label,cls='',disabled=false,attrs=''){return `<button type="button" data-action="${escapeHTML(action)}" class="${cls}" ${disabled?'disabled':''} ${attrs}>${label}</button>`;}
function scenarioById(id){return L.LAB_SCENARIOS.find(s=>s.id===id)||L.LAB_SCENARIOS[0];}
function setupView(){const scenario=scenarioById(setup.scenarioId),kit=setup.kit||scenario?.kit||'bulwark';return `<header class="lab-header"><div class="lab-header-inner"><div class="lab-brand">Crown & Calamity<small>Loop test bench · text-first</small></div><div class="disposable-banner">B.U.R.S.A.R. · disposable character · no saved adventures affected</div></div></header><main class="lab-shell lab-main" id="lab-main"><section class="intro"><div class="eyebrow">PLAYTEST LAB</div><h1>Test one loop at a time.</h1><p>Choose a focused scenario, start each encounter yourself, and record what felt clear or repetitive. This page uses disposable characters and never reads or writes the campaign save or character roster.</p></section><section class="panel"><div class="eyebrow">SCENARIO SETUP</div><h2>What are we checking?</h2><div class="setup-grid"><div class="field"><label for="scenario-select">Playtest prompt</label><select id="scenario-select">${L.LAB_SCENARIOS.map(s=>`<option value="${escapeHTML(s.id)}" ${s.id===setup.scenarioId?'selected':''}>${escapeHTML(s.title)}</option>`).join('')}</select></div><div class="field"><label for="kit-select">Starter kit</label><select id="kit-select">${Object.entries(KIT_NAMES).map(([id,name])=>`<option value="${id}" ${id===kit?'selected':''}>${name} · ${KIT_ACTIONS[id]}</option>`).join('')}</select></div><div class="field"><label for="seed-input">Random seed</label><input id="seed-input" type="text" value="${escapeHTML(setup.seed)}" maxlength="64" autocomplete="off"></div><div class="field"><label>Starting fixture</label><div class="status-chip">Level ${scenario.level} · Part ${scenario.part} · ${escapeHTML(G.ENEMIES.find(e=>e.id===scenario.enemy)?.name||scenario.enemy)}</div></div></div><p class="scenario-description"><strong>Prompt:</strong> ${escapeHTML(scenario.question)}<br><strong>Try:</strong> ${escapeHTML(scenario.task)}<br>${escapeHTML(scenario.description)}</p><div class="setup-actions"><span class="empty-copy">The setup creates a fresh attempt. It does not start a hunt or take an action.</span>${actionButton('start-session','Start disposable attempt','primary')}</div></section>${session?sessionView():''}${statAuditView()}</main><footer class="lab-footer"><p>B.U.R.S.A.R. · Local archive · Every encounter and rest requires your explicit tap.</p></footer>`;}
function statAuditView(){
  const audit=B.buildAudit(),marginal=B.marginalAudit();
  const pct=n=>(n*100).toFixed(2)+'%';
  return `<details class="panel stat-audit"><summary>Stat audit · provisional balance</summary><p>Equal attribute budgets at level 1, 5, and 10. These are expected-damage-per-action estimates using base-14 weapons, zero gear bonuses, rank-one actions, and a same-level baseline target with evasion 24 + 2 × level and no armor or ward. They exclude resource limits, cooldowns, opponent builds, and turn order. This is not a PvP match simulation or a win-rate prediction.</p><div class="audit-scroll" tabindex="0" role="region" aria-label="Equal-budget build estimates"><table><caption>Same budget, different attribute investments. Each damage column uses its own weapon channel; Arc Bolt costs mana.</caption><thead><tr><th scope="col">Level / build</th><th scope="col">Budget</th><th scope="col">HP</th><th scope="col">Mana</th><th scope="col">Stamina</th><th scope="col">Heavy attack</th><th scope="col">Precision attack</th><th scope="col">Arc Bolt</th><th scope="col">Critical</th><th scope="col">Gear drop</th></tr></thead><tbody>${audit.rows.map(row=>`<tr><th scope="row">${row.level} · ${escapeHTML(row.label)}</th><td>${row.budget}</td><td>${row.totals.hp}</td><td>${row.totals.mp}</td><td>${row.totals.sp}</td><td>${row.referenceExpectedDamage.might.expected.toFixed(1)}</td><td>${row.referenceExpectedDamage.precision.expected.toFixed(1)}</td><td>${row.referenceExpectedDamage.arcBolt.expected.toFixed(1)}</td><td>${pct(row.totals.critChance)}</td><td>${pct(row.totals.equipmentDropChance)}</td></tr>`).join('')}</tbody></table></div><p>One additional point from an all-8 baseline at level 1, before equipment. Chance changes below are percentage points; rounded damage can hide a small change.</p><div class="audit-scroll" tabindex="0" role="region" aria-label="One attribute point estimates"><table><caption>Marginal attribute effects · formula estimates, not a ranking</caption><thead><tr><th scope="col">Attribute</th><th scope="col">HP</th><th scope="col">Mana</th><th scope="col">Stamina</th><th scope="col">Physical accuracy</th><th scope="col">Spell accuracy</th><th scope="col">Evasion</th><th scope="col">Heavy damage</th><th scope="col">Precision damage</th><th scope="col">Arc damage</th><th scope="col">Crit pp</th><th scope="col">Drop pp</th></tr></thead><tbody>${Object.entries(marginal).map(([key,row])=>`<tr><th scope="row">${escapeHTML(G.ATTRS[key][0])}</th><td>+${row.totals.hp}</td><td>+${row.totals.mp}</td><td>+${row.totals.sp}</td><td>+${row.totals.physicalAcc}</td><td>+${row.totals.spellAcc}</td><td>+${row.totals.evasion}</td><td>+${row.referenceExpectedDamage.might.toFixed(2)}</td><td>+${row.referenceExpectedDamage.precision.toFixed(2)}</td><td>+${row.referenceExpectedDamage.arcBolt.toFixed(2)}</td><td>+${(row.critChance*100).toFixed(3)}</td><td>+${(row.equipmentDropChance*100).toFixed(3)}</td></tr>`).join('')}</tbody></table></div><p>Luck currently favors equipment acquisition over direct combat strength. Future PvP needs a player-defense resolver, fair turn submission, and burst/sustain testing before these numbers can be accepted.</p></details>`;
}
function resourceRow(name,current,max,kind){const ratio=max?Math.max(0,Math.min(100,current/max*100)):0;return `<div class="resource-row ${kind}"><label>${name}</label><div class="meter" role="meter" aria-label="${name}" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${current}"><i style="width:${ratio}%"></i></div><strong>${current} / ${max}</strong></div>`;}
function buildInspector(){if(!session)return '';const c=session.character,target=session.scenario.enemy,main=G.primaryActions(c),actions=[...new Set(['attack',main.skill,main.combined,'guard'])],attr=c.gear.weapon?({heavy:'mig',precision:'fin',spell:'int'}[G.ITEMS[c.gear.weapon]?.channel]||'mig'):'mig';const before=G.totals(c),profileBefore=G.actionProfile(c,main.skill,target);const afterState=JSON.parse(JSON.stringify(c));afterState.points=Math.max(1,afterState.points||0);const allocated=G.allocate(afterState,attr),after=G.totals(afterState),profileAfter=G.actionProfile(afterState,main.skill,target);const kitComparison=L.compareBuilds({enemyId:target,level:c.level,part:c.part||1,seed:session.seed});return `<section class="panel"><div class="eyebrow">BUILD INSPECTOR · ENGINE PREDICTION</div><h3>What does one point change?</h3><p>Current character and an isolated debug clone with one ${G.ATTRS[attr]?.[0]||attr} point allocated. The clone is not saved and does not change this attempt.</p><dl class="metrics-list"><dt>Heavy / precision / spell power</dt><dd>${before.heavyPower} / ${before.precisionPower} / ${before.spellPower}</dd><dt>Critical chance</dt><dd>${(before.critChance*100).toFixed(1)}%</dd><dt>Equipment-drop chance</dt><dd>${(before.equipmentDropChance*100).toFixed(1)}%</dd><dt>${G.actionInfo(c,main.skill)?.label||main.skill} average vs ${escapeHTML(G.ENEMIES.find(e=>e.id===target)?.name||target)}</dt><dd>${profileBefore?.average?.toFixed(1)||'—'} → ${allocated&&profileAfter?profileAfter.average.toFixed(1):'—'}</dd><dt>Power after debug point</dt><dd>${allocated?`${after.heavyPower} / ${after.precisionPower} / ${after.spellPower}`:'Unavailable'}</dd></dl><p class="empty-copy">Inspector prediction only; no combat roll ran. ${allocated?`Debug clone has ${afterState.points} remaining attribute point(s).`:''}</p>${actionButton('toggle-kit-comparison',compareAll?'Hide kit predictions':'Compare starter kits','subtle')}${compareAll&&kitComparison?kitComparisonView(kitComparison):''}</section>`;}
function kitComparisonView(report){return `<div class="compare-summary">${report.builds.map(b=>`<div class="compare-card"><strong>${escapeHTML(KIT_NAMES[b.kit]||b.kit)}</strong><small>${escapeHTML(b.actions.skillLabel)}: ${b.skill?.available?`${b.skill.averageDamage.toFixed(1)} average · ${Math.round(b.skill.hitChance*100)}% hit`:'unavailable'}<br>${escapeHTML(b.actions.combinedLabel)}: ${b.combined?.available?`${b.combined.averageDamage.toFixed(1)} average · ${b.combined.cost.stamina} stamina`:'unavailable'}</small></div>`).join('')}</div><p class="empty-copy">Inspector prediction only · ${escapeHTML(report.enemyName)} · no simulated fights.</p>`;}
function controlsView(){const c=session.character;if(!c.fight)return '';const primary=G.primaryActions(c),keys=[...new Set(['attack',primary.skill,primary.combined,'guard'])];for(const fallback of ['recover','withdraw','vent'])if(keys.length<4&&!keys.includes(fallback))keys.push(fallback);const remaining=G.actionDelayRemaining(c),waiting=remaining>0||attemptLock;const keyIcons={attack:'⚔',cast:'✧',combo:'◈',guard:'⛨',driving:'⚔',guardstrike:'⛨',recover:'↻',withdraw:'↗',brace:'⛨',disrupt:'✦',mend:'✚',aegis:'⛨',expose:'✧'};const mainSet=new Set(keys);const info=key=>G.actionInfo(c,key);const primaryHTML=keys.map((key,index)=>{const a=info(key);return `<button type="button" data-action="lab-action:${escapeHTML(key)}" class="action-button ${index===2?'featured':''}" ${waiting||a?.reason?'disabled':''} title="${escapeHTML(a?.reason||a?.desc||'')}" aria-label="${escapeHTML(a?.label||key)}. ${escapeHTML(a?.reason||a?.desc||'')}"><span aria-hidden="true">${keyIcons[key]||'✧'}</span><strong>${escapeHTML(a?.label||key)}</strong><small>${escapeHTML(a?.cost||'')}</small></button>`;}).join('');const skills=(c.equippedAbilities||[]).map(id=>[id==='arc'?'cast':id,G.ABILITIES[id]?.name||id]).filter(([key])=>!mainSet.has(key));const secondary=[...skills,['recover','Recover'],['withdraw','Withdraw']];const secondaryHTML=secondary.map(([key,label])=>{const a=info(key);return `<button type="button" data-action="lab-action:${escapeHTML(key)}" ${waiting||a?.reason?'disabled':''} title="${escapeHTML(a?.reason||a?.desc||'')}">${escapeHTML(a?.label||label)} · ${escapeHTML(a?.cost||'')}</button>`;}).join('');return `<section class="panel controls-panel ${waiting?'is-waiting':''}" id="controls-panel"><div class="eyebrow">ONE TAP · ONE EXCHANGE</div><div class="action-grid">${primaryHTML}</div><div class="secondary-actions">${secondaryHTML}</div><p class="empty-copy">+${G.MANA_REGEN_PER_EXCHANGE} mana after actions that spend none. Recover restores ${G.RECOVER_MANA_RESTORE+G.MANA_REGEN_PER_EXCHANGE} mana total and 10 stamina.</p><div class="delay-row"><span id="delay-copy">${waiting?'Shared 650 ms action delay · no queued actions':'Ready for your next action'}</span><span class="delay-track" aria-hidden="true"><i></i></span></div></section>`;}
function labShop(){const c=session.character,stock=Object.keys(G.ITEMS).filter(id=>G.ITEMS[id].price),owned=[...c.bag];return `<section class="panel"><div class="eyebrow">TEST OUTFITTER · REAL SHOP RULES</div><h3>Compare before spending.</h3><p>Purchases and equipment changes affect only this disposable character. Each purchase uses the engine shop preview and an explicit button.</p><div class="shop-fixtures">${stock.map(id=>{const item=G.resolveItem(c,id),preview=G.buyPreview(c,id),have=owned.includes(id),choices=have?G.slotChoices(c,id):[],slot=choices[0]||item.slot,current=c.gear[slot],gear={...c.gear,[slot]:id};for(const [k,v] of Object.entries(gear))if(k!==slot&&v===id)gear[k]=null;if(item.twoHanded)gear.offhand=null;const after=G.totals({...c,gear}),before=G.totals(c);return `<article class="shop-fixture"><div><strong>${escapeHTML(item.name)}</strong><small>${escapeHTML(G.SLOTS[item.slot]||item.slot)} · Level ${item.level} · ${item.price} coins</small><p>${escapeHTML(item.desc)}</p><small>On equip: Armor ${before.armor} → ${after.armor} · Ward ${before.ward} → ${after.ward}</small></div><div class="shop-actions">${have?`<span class="status-chip">Owned</span>${choices.map(target=>`<button type="button" data-action="lab-equip:${id}:${target}" ${c.gear[target]===id?'disabled':''}>Equip · ${escapeHTML(G.SLOTS[target]||target)}</button>`).join('')}`:actionButton(`lab-buy:${id}`,`Buy · ${preview.price} coins`,'subtle',!preview.allowed)}${preview.reason&&!have?`<small class="empty-copy">${escapeHTML(preview.reason)}</small>`:''}</div></article>`;}).join('')}</div></section>`;}
function storyGoal(c){const story=G.storyState?.(c);if(!story)return '';const current=story.active?.[0]||story.nextMajor;if(!current)return `<p><strong>Story:</strong> ${escapeHTML(story.title)} · ${escapeHTML(story.stageLabel)}</p>`;return `<div class="notice"><strong>Current goal · ${escapeHTML(current.title)}</strong><p>${escapeHTML(current.text)}</p>${current.objectives?.map(o=>`<span>${o.done?'✓':'○'} ${escapeHTML(o.label)} · ${o.current}/${o.target}</span>`).join('<br>')||''}</div>`;}
function sessionView(){const c=session.character,p=G.progression(c),enemy=c.fight&&G.ENEMIES.find(e=>e.id===c.fight.enemy),intent=G.intent(c),remaining=G.actionDelayRemaining(c),goal=session.scenario,summary=L.labSummary(session),story=storyGoal(c);const log=c.log||[];const totals=G.totals(c);return `<section class="panel"><div class="status-row"><span class="status-chip"><strong>Attempt:</strong> ${escapeHTML(KIT_NAMES[session.kit]||session.kit)}</span><span class="status-chip"><strong>Level:</strong> ${p.level} · Part ${p.part}/${p.parts}</span><span class="status-chip"><strong>Coins:</strong> ${c.coins}</span><span class="status-chip"><strong>Points:</strong> ${c.points}</span><span class="status-chip"><strong>Seed:</strong> ${escapeHTML(session.seed)}</span></div><h2>${escapeHTML(goal.title)}</h2><p><strong>Question:</strong> ${escapeHTML(goal.question)}<br><strong>Try:</strong> ${escapeHTML(goal.task)}</p>${story}<div class="resource-list">${resourceRow('Health',c.hp,totals.hp,'health')}${resourceRow('Mana',c.mp,totals.mp,'mana')}${resourceRow('Stamina',c.sp,totals.sp,'stamina')}</div></section><div class="session-grid"><div class="session-main">${enemy?`<section class="panel"><div class="enemy-head"><div><div class="eyebrow">${escapeHTML(enemy.location)} · ROUND ${c.fight.round+1}</div><h2>${escapeHTML(enemy.name)}</h2><p class="enemy-details">${escapeHTML(enemy.blurb)} · Level ${enemy.level} · Armor ${enemy.armor} · Ward ${enemy.ward}</p></div><span class="status-chip">${c.fight.hp} / ${enemy.hp} HP</span></div><div class="enemy-hp meter" role="meter" aria-label="Enemy health" aria-valuemin="0" aria-valuemax="${enemy.hp}" aria-valuenow="${c.fight.hp}"><i style="width:${Math.max(0,c.fight.hp/enemy.hp*100)}%"></i></div>${intent?`<div class="intent-box ${intent.heavy?'heavy':''}"><span aria-hidden="true">${intent.heavy?'⚠':'◇'}</span><div class="intent-copy"><strong>${escapeHTML(intent.name)} · about ${intent.damage} raw damage</strong><small>${intent.heavy?'Heavy attack: consider a Guard or Disrupt response.':'The enemy responds after your action.'}</small></div></div>`:''}</section>`:`<section class="panel"><div class="eyebrow">NO ENCOUNTER RUNNING</div><h3>Start the scenario hunt when you are ready.</h3><p>Starting a hunt only opens its encounter. It does not take an action or advance combat.</p>${actionButton('start-hunt',`Start ${escapeHTML(G.ENEMIES.find(e=>e.id===goal.enemy)?.name||goal.enemy)} hunt`,'primary',remaining>0)}${actionButton('rest','Rest at the Quay','subtle',false)}</section>`}${controlsView()}${labShop()}<section class="panel combat-log"><div class="eyebrow">RECENT COMBAT TEXT</div>${log.length?`<ol>${log.slice(0,12).map(row=>`<li>${escapeHTML(row.text)}</li>`).join('')}</ol>`:'<p class="empty-copy">No combat has happened yet. Start a hunt yourself to see actual engine messages.</p>'}</section><section class="panel"><div class="eyebrow">SESSION METRICS</div><dl class="metrics-list"><dt>Explicit inputs</dt><dd>${session.playerInputs}</dd><dt>Accepted exchanges</dt><dd>${session.rounds}</dd><dt>Engine-rejected inputs</dt><dd>${session.deniedInputs}</dd><dt>Encounters started</dt><dd>${session.encountersStarted}</dd><dt>Victories / defeats / withdrawals</dt><dd>${session.victories} / ${session.defeats} / ${session.withdrawals}</dd><dt>Reported damage attempts</dt><dd>${session.damageAttempted}</dd><dt>Unreported final attacks</dt><dd>${session.damageUnreportedActions}</dd><dt>Net HP lost / restored</dt><dd>${session.hpLost} / ${session.hpRestored}</dd><dt>Mana / stamina spent</dt><dd>${summary.counters.manaSpent} / ${summary.counters.staminaSpent}</dd><dt>Attribute points earned</dt><dd>${summary.counters.earnedPartPoints}</dd><dt>Shop attempts / completed</dt><dd>${session.shopActions.attempted} / ${session.shopActions.completed}</dd></dl><p class="empty-copy">Inputs blocked by disabled controls are not counted. Damage attempts include overkill. The engine omits attack damage on defeat/withdrawal; those attacks are counted separately. HP changes are net per exchange after healing, not exact incoming damage.</p></section></div><aside class="session-side"><section class="panel"><div class="eyebrow">CURRENT BUILD</div><h3>${escapeHTML(G.resolveItem(c,c.gear.weapon)?.name||c.gear.weapon)}</h3><p>${escapeHTML(KIT_ACTIONS[session.kit]||'')}</p><dl class="metrics-list"><dt>Weapon channel</dt><dd>${escapeHTML(G.ITEMS[c.gear.weapon]?.channel||'—')}</dd><dt>Armor / ward</dt><dd>${totals.armor} / ${totals.ward}</dd><dt>Hit / critical</dt><dd>${Math.round(G.actionProfile(c,G.primaryActions(c).skill,goal.enemy)?.hitChance*100||0)}% / ${(totals.critChance*100).toFixed(1)}%</dd><dt>Drop chance</dt><dd>${(totals.equipmentDropChance*100).toFixed(1)}%</dd><dt>Full-level XP</dt><dd>${p.levelXP} / ${p.levelRequired||'cap'}</dd><dt>Next point</dt><dd>${p.partXP} / ${p.partRequired||'—'} XP</dd></dl></section>${buildInspector()}</aside></div>${reflectionView()}`;}
function reflectionView(){return `<section class="panel"><div class="eyebrow">PLAYER REFLECTION · SELF-REPORTED</div><h2>What was I working toward?</h2><p>Your ratings are your answers, not measured player behavior. Notes are stored only in this disposable session report.</p><div class="reflection-grid">${[['satisfaction','How satisfying did it feel?'],['clarity','How clear was the next step?'],['repetition','How repetitive did it feel?']].map(([id,label])=>`<div class="rating-field"><label for="rating-${id}">${label}</label><select id="rating-${id}"><option value="">Choose a rating</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${ratings[id]===String(n)?'selected':''}>${n} · ${['','Very low','Low','Mixed','High','Very high'][n]}</option>`).join('')}</select></div>`).join('')}</div><label class="field" for="session-notes" style="margin-top:14px">Optional notes<textarea id="session-notes" maxlength="4000" placeholder="What felt obvious, confusing, useful, or repetitive?">${escapeHTML(session.notes)}</textarea></label><div class="export-actions" style="margin-top:14px">${actionButton('export-report','Export JSON','primary')}${actionButton('copy-report','Copy report','subtle')}${actionButton('reset-session','Reset disposable attempt','subtle')}</div></section>`;}
function buildReport(){L.setLabNotes(session,document.querySelector('#session-notes')?.value||session.notes);return {report:L.labSummary(session),reflection:{ratings:{...ratings},ratingMode:'User-entered, not measured',question:'What was I working toward?',notes:session.notes}};}
function render(){clearTimeout(delayTimer);app.innerHTML=setupView();if(session){const remaining=G.actionDelayRemaining(session.character),controls=document.querySelector('#controls-panel');controls?.classList.toggle('is-waiting',remaining>0);if(remaining>0)delayTimer=setTimeout(render,remaining+15);}}
async function copyReport(){const report=JSON.stringify(buildReport(),null,2);try{await navigator.clipboard.writeText(report);toast('Session report copied.');}catch{toast('Clipboard is unavailable. Use Export JSON instead.');}}
function exportReport(){const data=JSON.stringify(buildReport(),null,2),blob=new Blob([data],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`crown-calamity-playtest-${session.scenarioId}-${Date.now()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Disposable playtest report exported.');}
function handleAction(action){if(action==='start-session'){const scenarioId=document.querySelector('#scenario-select').value,kit=document.querySelector('#kit-select').value,seed=document.querySelector('#seed-input').value||'1';session=L.createLabSession({scenarioId,kit,seed});setup={scenarioId,kit,seed};ratings={satisfaction:'',clarity:'',repetition:''};compareAll=false;if(!session)toast('That test fixture could not be created.');render();window.scrollTo({top:0,behavior:'smooth'});return;}if(action==='start-hunt'){if(!session)return;const ok=L.startLabHunt(session,session.scenario.enemy);if(!ok)toast('The selected hunt could not be started.');render();return;}if(action.startsWith('lab-action:')){if(!session||attemptLock||G.actionDelayRemaining(session.character)>0)return;attemptLock=true;const key=action.slice('lab-action:'.length);const result=L.labAction(session,key);attemptLock=false;if(result.retryAfterMs)toast(`Action delay · ${Math.ceil(result.retryAfterMs)} ms. Your action was not queued.`);else if(!result.ok&&result.reason)toast(result.reason);render();return;}if(action==='rest'){if(L.labRest(session))toast('Rested at the Quay. Resources restored.');else toast('Rest is unavailable during an encounter.');render();return;}if(action==='toggle-kit-comparison'){compareAll=!compareAll;render();return;}if(action.startsWith('lab-buy:')){const id=action.slice(8),receipt=L.labUse(session,'buy',id);if(receipt)toast(`${G.resolveItem(session.character,id)?.name||id} bought for ${G.buyPreview(session.character,id).price} coins.`);else toast(G.buyPreview(session.character,id).reason||'Purchase unavailable.');render();return;}if(action.startsWith('lab-equip:')){const [,id,slot]=action.split(':');const ok=L.labUse(session,'equip',id,slot);if(ok)toast(`${G.resolveItem(session.character,id)?.name||id} equipped.`);else toast('That item cannot be equipped in this slot.');render();return;}if(action==='export-report'){exportReport();return;}if(action==='copy-report'){copyReport();return;}if(action==='reset-session'){const scenarioId=session.scenarioId,kit=session.kit,seed=session.seed;session=L.createLabSession({scenarioId,kit,seed});ratings={satisfaction:'',clarity:'',repetition:''};compareAll=false;render();window.scrollTo({top:0,behavior:'smooth'});return;}}
app.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button&&!button.disabled)handleAction(button.dataset.action);});
app.addEventListener('change',event=>{if(event.target.id==='scenario-select'){setup.scenarioId=event.target.value;setup.kit=scenarioById(setup.scenarioId)?.kit||'bulwark';render();}else if(event.target.id==='kit-select')setup.kit=event.target.value;else if(event.target.id==='seed-input')setup.seed=event.target.value;else if(event.target.id.startsWith('rating-'))ratings[event.target.id.slice(7)]=event.target.value;});
app.addEventListener('input',event=>{if(event.target.id==='session-notes'&&session)L.setLabNotes(session,event.target.value);});
render();
